package com.donotmiss.backend.aiapplication.career.job;

import com.donotmiss.backend.aiapplication.agent.*; import com.donotmiss.backend.aiapplication.llm.*; import com.donotmiss.backend.aiapplication.trace.TraceService; import com.fasterxml.jackson.databind.ObjectMapper; import org.junit.jupiter.api.Test; import java.time.Instant; import java.util.*; import static org.assertj.core.api.Assertions.assertThat; import static org.mockito.ArgumentMatchers.any; import static org.mockito.Mockito.*;
class JobRequirementExtractionRuntimeTest {
 @Test void drivesJobAgentThroughRuntimeToolAndGateway(){LlmGateway gateway=mock(LlmGateway.class);TraceService trace=mock(TraceService.class);when(gateway.complete(any())).thenReturn(Optional.of(new LlmResponse("{\"requirements\":[{\"skill\":\"Java\",\"importance\":4,\"requiredLevel\":\"mid\",\"requirementText\":\"Java\",\"sourcePosition\":1}]}","mock",new LlmUsage(1,1,2),"stop",1,"r",Map.of())));JobRequirementExtractionTool tool=new JobRequirementExtractionTool(gateway,new ObjectMapper());AgentRuntime runtime=new SimpleAgentRuntime(name->Optional.of(tool),trace);AgentResult result=runtime.run(new JobRequirementExtractionAgent(),new AgentContext(1L,2L,"u","job-requirement-extraction-agent","extract",AgentState.PREPARING,Map.of("jobText","Java","chunks",List.of("Java"),"jobVersionHash","h"),List.of(),Instant.now()));assertThat(result.nextState()).isEqualTo(AgentState.COMPLETED);assertThat(result.output()).containsKey("structuredJobDescriptionJson");verify(gateway).complete(any(LlmRequest.class));verify(trace).recordToolInvocation(any(AgentToolInvocation.class));}
}
